#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/mise/tasks/code-sec.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Security check (grype + osv-scanner + gitleaks)"
# MISE tools={uv="latest", python="3.14"}

# USAGE flag "--debug" help="emit debug logs"
# USAGE flag "--staged" help="scan only the staged changes for secrets, and skip grype (for the pre-commit hook)"

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def main():
  staged = ["--staged"] if os.environ.get("usage_staged", "false") == "true" else []
  debug = ["--debug"] if os.environ.get("usage_debug", "false") == "true" else []

  # The hook scans what is staged: the commit is the content that leaves the
  # machine. grype reads the lockfiles of the whole tree, so it belongs to the
  # full run and to CI, not to each commit.
  if staged:
    helpers.print_header("Scanning the staged changes for secrets ...")
  else:
    helpers.print_header("Scanning for security problems ...")

  # The scanners of the pack base must be there: own_tasks skips a missing
  # or non-executable task without a word, and the gate would pass unscanned.
  for task in ("code:sec:10-gitleaks", "code:sec:20-grype", "code:sec:30-osv-scanner"):
    if not helpers.has_own_task(task):
      helpers.print_error(f"The task {task} is missing or not executable - run mise run init")
      sys.exit(1)

  # Each code:sec:<scanner> task, from a scanner tool or from this repository.
  # With --staged, a scanner that has no staged mode prints nothing.
  for task in helpers.own_tasks("code:sec"):
    rc = subprocess.run(["mise", "run", task, *staged, *debug], check=False).returncode
    if rc:
      sys.exit(128 - rc if rc < 0 else rc)

  if not staged:
    helpers.print_success("Scanning done")


if __name__ == "__main__":
  main()
